package com.jnapanam.sportszone.loyalty.service;import com.jnapanam.sportszone.common.exception.*;import com.jnapanam.sportszone.identity.model.User;import com.jnapanam.sportszone.identity.repository.UserRepository;import com.jnapanam.sportszone.loyalty.dto.*;import com.jnapanam.sportszone.loyalty.model.*;import com.jnapanam.sportszone.loyalty.repository.*;import com.jnapanam.sportszone.payment.model.PaymentOrder;import java.util.UUID;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service public class LoyaltyService{private final LoyaltyWalletRepository wallets;private final LoyaltyTransactionRepository transactions;private final UserRepository users;private final long pointValue;private final long earnPerHundred;private final int maxPercent;public LoyaltyService(LoyaltyWalletRepository w,LoyaltyTransactionRepository t,UserRepository u,@Value("${app.loyalty.point-value-paise:100}")long pointValue,@Value("${app.loyalty.earn-per-100-rupees:1}")long earn,@Value("${app.loyalty.max-redemption-percent:20}")int max){wallets=w;transactions=t;users=u;this.pointValue=pointValue;earnPerHundred=earn;maxPercent=max;}@Transactional public long redeem(User user,long requested,long originalAmount){if(requested<=0)return 0;long capPoints=(originalAmount*maxPercent/100)/pointValue;long points=Math.min(requested,capPoints);if(points<=0)throw new ConflictException("Loyalty redemption is below the allowed value");LoyaltyWallet w=locked(user);w.redeem(points);return points;}@Transactional public void recordRedemption(User user,PaymentOrder order,long points){if(points>0)transactions.save(new LoyaltyTransaction(user,order,LoyaltyTransactionType.REDEEM,-points,"Redeemed against "+order.getReceiptNumber()));}@Transactional public void earn(User user,PaymentOrder order){if(transactions.existsByPaymentOrderIdAndType(order.getId(),LoyaltyTransactionType.EARN))return;long points=(order.getAmountPaise()/10000)*earnPerHundred;if(points>0){LoyaltyWallet w=locked(user);w.earn(points);order.loyaltyEarned(points);transactions.save(new LoyaltyTransaction(user,order,LoyaltyTransactionType.EARN,points,"Earned from "+order.getReceiptNumber()));}}@Transactional(readOnly=true)public LoyaltyResponse mine(UUID userId){LoyaltyWallet w=wallets.findById(userId).orElse(null);var entries=transactions.findTop100ByUserIdOrderByCreatedAtDesc(userId).stream().map(x->new LoyaltyResponse.Entry(x.getType().name(),x.getPoints(),x.getDescription(),x.getCreatedAt())).toList();return new LoyaltyResponse(w==null?0:w.getPointsBalance(),w==null?0:w.getLifetimeEarned(),w==null?0:w.getLifetimeRedeemed(),pointValue,w==null?null:w.getUpdatedAt(),entries);}@Transactional public LoyaltyResponse adjust(UUID userId,long points,String reason){User u=users.findById(userId).orElseThrow(()->new NotFoundException("User not found"));LoyaltyWallet w=locked(u);w.adjust(points);transactions.save(new LoyaltyTransaction(u,null,LoyaltyTransactionType.ADJUSTMENT,points,reason.trim()));return mine(userId);}public long pointValue(){return pointValue;}private LoyaltyWallet locked(User u){return wallets.findLocked(u.getId()).orElseGet(()->wallets.saveAndFlush(new LoyaltyWallet(u)));}}
